func eventFormDisclosureID(form EventForm) string {
	if form.Editing {
		return "editar-evento"
	}
	return "criar-evento"
}
func eventFormClass(form EventForm) string {
	if form.TaskRoute {
		return "module disclosure"
	}
	return "module disclosure create-panel"
}
func eventCreateForm(form EventForm) EventForm { form.Open = true; form.TaskRoute = true; return form }
func eventFormTitle(form EventForm) string {
	if form.Editing {
		return "Dados do evento"
	}
	return "Criar evento"
}
func eventFormSummary(form EventForm) string {
	if form.Editing {
		return "Atualize data, lotação e participantes."
	}
	return "Defina data, lotação e participantes."
}
func eventFormAction(form EventForm) string {
	if form.Editing {
		return "/admin/events/" + form.ID
	}
	return "/admin/events"
}
