func eventPageActions(page EventsPage) []components.PageAction {
	if page.Management {
		return []components.PageAction{{Label: "Criar evento", Href: "/admin/eventos/criar", Variant: "primary"}}
	}
	return nil
}

func eventPageURL(page EventsPage, id string) string {
	if page.Management {
		return "/admin/eventos/" + id
	}
	return "/events/" + id + page.DetailQuery
}
func eventDetailArea(page EventDetailPage) string {
	if page.CanManageEvents {
		return "Coordenação · Eventos"
	}
	return "Evento"
}
func eventDetailBackURL(page EventDetailPage) string {
	if page.CanManageEvents {
		return "/admin/eventos"
	}
	if page.CollectionURL != "" {
		return page.CollectionURL
	}
	return "/events"
}
func eventDetailActions(page EventDetailPage) []components.PageAction {
	actions := []components.PageAction{{Label: "Voltar aos eventos", Href: eventDetailBackURL(page), Variant: "quiet"}}
	if page.CanManageEvents && page.Editable {
		actions = append([]components.PageAction{{Label: "Editar evento", Href: "/admin/eventos/" + page.ID + "/editar", Variant: "primary"}}, actions...)
	}
	return actions
}

func eventStatusTone(status string) string {
	switch status {
	case "Vou", "Confirmado", "Presente":
		return "success"
	case "Em lista de espera", "Pendente":
		return "warning"
	case "Não vou", "Fora do prazo", "Cancelado":
		return "error"
	default:
		return "selected"
	}
}

func eventTypeTone(eventType string) string {
	if eventType == "Competição" {
		return "selected"
	}
	return "neutral"
}

func eventParticipationDescription(past bool) string {
	if past {
		return "Consulte a resposta registada para este evento."
	}
	return "Confirme a participação da pessoa certa."
}

